import{_ as e,o as a,c as n,ag as s}from"./chunks/framework.CxkNbRKf.js";const u=JSON.parse('{"title":"NADA-AI search","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/nada-ai.md","filePath":"admin-guide/web-ui/nada-ai.md","lastUpdated":1794965376000}'),r={name:"admin-guide/web-ui/nada-ai.md"};function i(o,t,d,h,l,g){return a(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="nada-ai-search" tabindex="-1">NADA-AI search <a class="header-anchor" href="#nada-ai-search" aria-label="Permalink to &quot;NADA-AI search&quot;">​</a></h1><p><a href="https://github.com/mah0001/nada-ai" target="_blank" rel="noreferrer">NADA-AI</a> is an <strong>optional</strong> search service that adds <strong>semantic search</strong> to the catalog. With it, a search for &quot;household spending&quot; also finds studies about &quot;consumption expenditure&quot;, and a query in French or Spanish finds English titles. It serves the catalog&#39;s study, variable and citation searches from its own OpenSearch indexes.</p><p>NADA keeps NADA-AI&#39;s index in step with the catalog: every change to a study or citation is queued, and NADA-AI picks it up within minutes. You manage all of this from <strong>Settings → Search index</strong>.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li>NADA-AI is installed and running: <a href="/nada-documentation/installation-guide/installation-nada-ai.html">NADA-AI installation (Docker)</a>.</li><li>You have the URL NADA&#39;s server uses to reach it (often <code>http://127.0.0.1:8020</code>) and the <strong>admin key</strong> created for NADA in the last installation step.</li><li>You are a site administrator, or have the permissions below.</li></ul><h2 id="overview-of-the-steps" tabindex="-1">Overview of the steps <a class="header-anchor" href="#overview-of-the-steps" aria-label="Permalink to &quot;Overview of the steps&quot;">​</a></h2><ol><li><a href="#_1-grant-permissions">Grant permissions</a> to the staff who manage the index.</li><li><a href="#_2-connect-nada">Connect NADA</a> to NADA-AI and start tracking changes.</li><li><a href="#_3-build-the-index">Build the index</a> while the database keeps serving searches.</li><li><a href="#_4-test-the-search">Test</a> the search.</li><li><a href="#_5-switch-the-catalog-to-nada-ai">Switch the catalog</a> to NADA-AI.</li></ol><hr><h2 id="_1-grant-permissions" tabindex="-1">1. Grant permissions <a class="header-anchor" href="#_1-grant-permissions" aria-label="Permalink to &quot;1. Grant permissions&quot;">​</a></h2><p>The <strong>Search index</strong> permission group controls the Search index page:</p><table tabindex="0"><thead><tr><th>Permission</th><th>Allows</th></tr></thead><tbody><tr><td><strong>view</strong></td><td>Open the page: status, coverage, jobs, change queue, test search</td></tr><tr><td><strong>edit</strong></td><td>Start indexing, cancel jobs, requeue, pause and resume</td></tr><tr><td><strong>delete</strong></td><td>Rebuild or delete the whole index</td></tr></tbody></table><p>Add them to a role in <a href="/nada-documentation/admin-guide/web-ui/users.html#defining-roles">Users → Roles</a>. Site administrators have them already. Changing the search settings themselves needs permission to edit site configurations.</p><hr><h2 id="_2-connect-nada" tabindex="-1">2. Connect NADA <a class="header-anchor" href="#_2-connect-nada" aria-label="Permalink to &quot;2. Connect NADA&quot;">​</a></h2><ol><li><p>Open <strong>Settings → Settings</strong> (<a href="./site-configurations.html">Site configurations</a>) and go to the <strong>Search</strong> section.</p></li><li><p>Expand the <strong>NADA-AI</strong> panel. Do not select its radio button yet.</p></li><li><p>Under <strong>Connection</strong>, fill in:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>NADA-AI API URL</strong></td><td>Where NADA&#39;s server reaches NADA-AI, without a trailing slash, e.g. <code>http://127.0.0.1:8020</code> or <code>https://nada-ai.example.org</code></td></tr><tr><td><strong>NADA-AI API Key</strong></td><td>The admin key created for NADA. It is stored and never shown again</td></tr></tbody></table></li><li><p>Under <strong>Search behaviour</strong>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Choose</th></tr></thead><tbody><tr><td><strong>When NADA-AI is unavailable</strong></td><td><strong>Serve the search from the catalog database</strong> (recommended), or <strong>Show an error</strong></td></tr><tr><td><strong>Multilingual search</strong></td><td><strong>Yes</strong> with the default embedding model, which matches queries across languages. The home page then shows example searches in several languages</td></tr></tbody></table></li><li><p>Leave <strong>Advanced → NADA-AI debug</strong> off, except while troubleshooting.</p></li><li><p>Below the panels, set <strong>Index kept in sync</strong> to <strong>NADA-AI</strong>.</p></li><li><p>Click <strong>Update</strong> to save.</p></li></ol><p>The top of the section now shows <em>Catalog search uses: Database (built-in)</em> and <em>Index kept in sync: NADA-AI</em>. From this moment NADA records every study and citation change for NADA-AI, while the public catalog still searches the database.</p><div class="tip custom-block"><p class="custom-block-title">Why two settings</p><p><strong>Index kept in sync</strong> decides which index NADA keeps up to date. <strong>Search engine</strong> decides which engine answers searches. Setting the first one alone lets you build and check the index before visitors use it. The search engine can only be the database or the engine whose index is kept in sync; NADA refuses any other combination.</p></div><hr><h2 id="_3-build-the-index" tabindex="-1">3. Build the index <a class="header-anchor" href="#_3-build-the-index" aria-label="Permalink to &quot;3. Build the index&quot;">​</a></h2><ol><li>Open <strong>Settings → Search index</strong>. The <strong>Overview</strong> page opens.</li><li>Check the <strong>Search engine</strong> card and the health strip at the top. Both should show NADA-AI answering. If a banner says NADA-AI is not answering, check the URL and key from step 2.</li><li>Click <strong>Warm up</strong> in the health strip to load the embedding model.</li><li>Open <strong>Indexing</strong> and click <strong>Update all</strong>. NADA queues every published study and citation that is not in the index yet. NADA-AI then works through the queue on its own.</li><li>On the <strong>Overview</strong> page, the <strong>Variables</strong> card shows how many variables are indexed. If it reports variables not indexed after the studies are done, click its <strong>Update</strong>.</li></ol><p>Indexing a large catalog the first time takes hours. Follow it on the <strong>Activity</strong> page, or in the <strong>Indexing activity</strong> card on the Overview, which shows what is being indexed and an estimate of the time left. Search keeps working from the database meanwhile, and catalog edits made during the build are queued too.</p><hr><h2 id="_4-test-the-search" tabindex="-1">4. Test the search <a class="header-anchor" href="#_4-test-the-search" aria-label="Permalink to &quot;4. Test the search&quot;">​</a></h2><p>Open <strong>Test search</strong>. It runs the catalog search exactly as the public catalog would with NADA-AI as the search engine, and shows each result&#39;s score and the search driver&#39;s debug output.</p><p>Try a few searches your users make, including ones phrased differently from the titles. Compare the results with the public catalog, which still uses the database.</p><hr><h2 id="_5-switch-the-catalog-to-nada-ai" tabindex="-1">5. Switch the catalog to NADA-AI <a class="header-anchor" href="#_5-switch-the-catalog-to-nada-ai" aria-label="Permalink to &quot;5. Switch the catalog to NADA-AI&quot;">​</a></h2><p>When the <strong>Overview</strong> shows the studies as searchable:</p><ol><li>Open <strong>Settings → Settings</strong>, section <strong>Search</strong>.</li><li>Select the radio button on the <strong>NADA-AI</strong> panel.</li><li>Click <strong>Update</strong>.</li></ol><p>Search the public catalog to confirm. To go back at any time, select <strong>Database (built-in)</strong> and save; the index stays in sync as long as <strong>Index kept in sync</strong> is NADA-AI.</p><hr><h2 id="the-search-index-page" tabindex="-1">The Search index page <a class="header-anchor" href="#the-search-index-page" aria-label="Permalink to &quot;The Search index page&quot;">​</a></h2><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p><em>Is the search index working, and what can be found with it.</em></p><table tabindex="0"><thead><tr><th>Part</th><th>What it tells you</th></tr></thead><tbody><tr><td><strong>Health strip</strong></td><td>Whether NADA-AI, its OpenSearch backend, the index and the embedding model are all answering. <strong>Details</strong> shows more, including embedding drift (a model change that needs a rebuild). <strong>Warm up</strong> loads the model</td></tr><tr><td><strong>Search engine</strong> card</td><td>Which engine serves studies, variables and citations now, what NADA-AI can serve, and whether NADA-AI is paused or unreachable. <strong>Settings</strong> opens Site configurations</td></tr><tr><td><strong>What is searchable</strong></td><td>Per data type: studies in the catalog, searchable, to add, to remove, and errors</td></tr><tr><td><strong>Variables</strong> and <strong>Citations</strong> cards</td><td>Database counts against indexed counts, with <strong>Update</strong> to catch up</td></tr><tr><td><strong>Indexing activity</strong></td><td>What NADA-AI is doing now, how much is waiting, and the time left. <strong>Pause</strong> and <strong>Resume</strong> are here</td></tr><tr><td><strong>Recent changes</strong></td><td>Catalog edits waiting to be indexed, and the ones indexed last</td></tr></tbody></table><h3 id="indexing" tabindex="-1">Indexing <a class="header-anchor" href="#indexing" aria-label="Permalink to &quot;Indexing&quot;">​</a></h3><p><em>Keep the search index in step with the catalog.</em></p><table tabindex="0"><thead><tr><th>Part</th><th>Use</th></tr></thead><tbody><tr><td><strong>Update all</strong>, <strong>Update</strong> per type</td><td>Queues studies missing from the index and the ones no longer in the catalog. Use it for routine catch-up</td></tr><tr><td><strong>Studies to add</strong></td><td>Published studies that are not searchable yet, with the last error if indexing failed. <strong>Index</strong> retries one</td></tr><tr><td><strong>Studies to remove</strong></td><td>Studies still in the index but no longer in the catalog. <strong>Update</strong> or <strong>Clean up</strong> removes them</td></tr><tr><td><strong>Force re-index…</strong></td><td>Reads every study of a type again, including those already indexed, as a job outside the queue. Use it after an upgrade that changes how metadata is read, or when one type looks wrong. Microdata studies re-index their variables too</td></tr><tr><td><strong>Maintenance</strong></td><td>Repairs and rebuilds, see below</td></tr></tbody></table><p><strong>Maintenance actions:</strong></p><table tabindex="0"><thead><tr><th>Action</th><th>When to use it</th><th>Needs</th></tr></thead><tbody><tr><td><strong>Clean up</strong></td><td>Remove studies and citations no longer in the catalog</td><td>edit</td></tr><tr><td><strong>Restore tracking</strong></td><td>After switching engines: NADA-AI reports what it already holds, so NADA does not index it all again</td><td>edit</td></tr><tr><td><strong>Rebuild the study index</strong></td><td>The Overview asks for it after an upgrade. Embeddings are reused, so it is much faster than a full rebuild</td><td>delete</td></tr><tr><td><strong>Rebuild the variable / citation index</strong></td><td>The Overview asks for it after an upgrade</td><td>delete</td></tr><tr><td><strong>Delete and rebuild</strong></td><td>Start over: empties every index and indexes everything again, embeddings included. Slow. Type <code>RECREATE</code> to confirm</td><td>delete</td></tr><tr><td><strong>Delete index</strong></td><td>Empties every index and indexes nothing. Searches fail until you rebuild. Type <code>DELETE</code> to confirm</td><td>delete</td></tr></tbody></table><p>When the health strip lists indexes &quot;created before a change to what they hold&quot;, they reject updates until rebuilt. Use <strong>Rebuild the study index</strong> for the study index, or <strong>Delete and rebuild</strong> for the others.</p><h3 id="activity" tabindex="-1">Activity <a class="header-anchor" href="#activity" aria-label="Permalink to &quot;Activity&quot;">​</a></h3><p><em>Indexing jobs, and catalog edits waiting to be applied.</em></p><ul><li><strong>Change queue</strong>: catalog edits waiting for NADA-AI, and the ones that failed. <strong>Process now</strong> asks NADA-AI to start at once instead of at its next check. <strong>Requeue failed</strong> tries the failed ones again. The header shows whether change tracking is on, when NADA-AI last read the queue, and the last full sync.</li><li><strong>Jobs</strong>: indexing runs started by hand (Force re-index, variable or citation sync, Restore tracking), with progress, errors and <strong>Cancel</strong>. Catalog edits are not jobs; they go through the change queue.</li></ul><h3 id="test-search" tabindex="-1">Test search <a class="header-anchor" href="#test-search" aria-label="Permalink to &quot;Test search&quot;">​</a></h3><p>Runs a query against the live index with filters and options, as described in <a href="#_4-test-the-search">step 4</a>.</p><hr><h2 id="day-to-day" tabindex="-1">Day to day <a class="header-anchor" href="#day-to-day" aria-label="Permalink to &quot;Day to day&quot;">​</a></h2><p>Nothing needs to be done by hand. When a study or citation is published, edited, unpublished or deleted, NADA queues the change and NADA-AI applies it within a few minutes.</p><p>Check the <strong>Search index</strong> page from time to time, or when users report missing results:</p><ul><li>a red badge on <strong>Indexing</strong> counts studies that failed to index; the error is listed under <strong>Studies to add</strong>;</li><li>a badge on <strong>Activity</strong> counts failed queue items, or what is waiting.</li></ul><p>To stop indexing for a while, for example during a large import, click <strong>Pause</strong> in the <strong>Indexing activity</strong> card. NADA-AI finishes the item in hand and waits. Changes keep queuing and are applied after <strong>Resume</strong>.</p><h2 id="when-nada-ai-is-unavailable" tabindex="-1">When NADA-AI is unavailable <a class="header-anchor" href="#when-nada-ai-is-unavailable" aria-label="Permalink to &quot;When NADA-AI is unavailable&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>What visitors see</th></tr></thead><tbody><tr><td>NADA-AI is down, times out or is overloaded</td><td>With <strong>Serve the search from the catalog database</strong>, normal database results. With <strong>Show an error</strong>, an error message</td></tr><tr><td>NADA-AI rejects the request, e.g. a wrong key</td><td>An error, whatever the outage setting: this is a configuration problem</td></tr><tr><td>NADA-AI does not offer a search, e.g. citations</td><td>The database serves it</td></tr></tbody></table><p>After a failure that means NADA-AI is down, NADA stops calling it for 30 seconds, then tries one request. Searches do not each wait for a timeout meanwhile. The <strong>Search engine</strong> card shows when NADA-AI is not answering. The admin API <code>GET /api/admin/semantic/engine_status</code> also reports how many searches fell back to the database in the last hour.</p><p>NADA-AI must run OpenSearch. If it runs anything else, catalog searches fail with a message naming both, and the Search index page shows a banner.</p><h2 id="switching-away-from-nada-ai" tabindex="-1">Switching away from NADA-AI <a class="header-anchor" href="#switching-away-from-nada-ai" aria-label="Permalink to &quot;Switching away from NADA-AI&quot;">​</a></h2><ul><li><strong>Back to database search:</strong> select <strong>Database (built-in)</strong> in the Search section and save. Keep <strong>Index kept in sync</strong> on NADA-AI to keep the index current for a later switch back.</li><li><strong>Stop using NADA-AI:</strong> set <strong>Index kept in sync</strong> to <strong>None</strong>. Changes stop being queued. When you return, use <strong>Restore tracking</strong> on the Indexing page, then <strong>Update all</strong>.</li></ul><h2 id="upgrading-from-earlier-semantic-search-settings" tabindex="-1">Upgrading from earlier semantic search settings <a class="header-anchor" href="#upgrading-from-earlier-semantic-search-settings" aria-label="Permalink to &quot;Upgrading from earlier semantic search settings&quot;">​</a></h2><p>Sites that used the earlier &quot;semantic&quot; search settings are converted by the database migration:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> index.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli/migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> latest</span></span></code></pre></div><p>It renames the settings, sets <strong>Search engine</strong> to NADA-AI where semantic search was in use, and sets <strong>Index kept in sync</strong> to match. Earlier separate search and admin keys become one key; check that the stored key is a NADA-AI <strong>admin</strong> key. NADA&#39;s former built-in OpenSearch engine has been removed; sites that used it are switched back to the database. Back up the database first. See <a href="/nada-documentation/installation-guide/database-migrations-cli.html">Database migrations (CLI)</a>.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Issue</th><th>What to check</th></tr></thead><tbody><tr><td>Cannot select NADA-AI</td><td>Enter the <strong>NADA-AI API URL</strong> first. The search engine also requires <strong>Index kept in sync</strong> to be NADA-AI</td></tr><tr><td>Banner: NADA-AI is not answering</td><td>NADA-AI is running (<code>/health</code> on its host); the URL is reachable from NADA&#39;s server; firewall</td></tr><tr><td>Banner: the search engine is set to NADA-AI, but NADA-AI is running another engine</td><td>NADA-AI was started with a non-OpenSearch backend. Restart it with OpenSearch</td></tr><tr><td>Indexing actions greyed out</td><td>You have <strong>view</strong> only, or <strong>Index kept in sync</strong> is not NADA-AI</td></tr><tr><td>Errors when searching or indexing, <code>401</code> or <code>403</code></td><td>The <strong>NADA-AI API Key</strong> is wrong or is not an admin key. Enter it again and save</td></tr><tr><td>Queue grows but nothing is indexed</td><td>NADA-AI is paused (Indexing activity card), or cannot reach NADA. Check NADA-AI&#39;s logs and its NADA API key</td></tr><tr><td>Studies fail with errors under <strong>Studies to add</strong></td><td>Read the error. A metadata problem in one study does not stop the others; fix the study, then <strong>Index</strong> it again</td></tr><tr><td>Variables not indexed</td><td>NADA-AI&#39;s NADA user lacks <strong>Studies</strong> view. See <a href="/nada-documentation/installation-guide/installation-nada-ai.html#the-nada-api-key-for-nada-ai">the NADA API key</a></td></tr><tr><td>Search results look outdated after an upgrade</td><td>The health strip asks for a rebuild. Use <strong>Maintenance</strong></td></tr><tr><td>Need the raw requests and responses</td><td>Turn on <strong>NADA-AI debug</strong> briefly; the details appear in NADA&#39;s logs and in catalog API errors for administrators</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/nada-documentation/installation-guide/installation-nada-ai.html">NADA-AI installation (Docker)</a></li><li><a href="./site-configurations.html#search">Site configurations</a>: the Search section</li><li><a href="./solr.html">Solr search</a>: the other optional search engine</li><li><a href="/nada-documentation/installation-guide/installation-mcp.html">MCP server</a>: connect AI assistants to the catalog, list of tools</li><li>NADA-AI documentation: <a href="https://github.com/mah0001/nada-ai/blob/main/docs/nada-search-engine-settings.md" target="_blank" rel="noreferrer">NADA search engine settings</a>, <a href="https://github.com/mah0001/nada-ai/blob/main/docs/mcp.md" target="_blank" rel="noreferrer">MCP guide</a></li></ul>',66)])])}const A=e(r,[["render",i]]);export{u as __pageData,A as default};
